import json
n=16
g=[[0]*n for _ in range(n)]
for r in range(n):
    for c in range(n):
        if r==c+2: g[r][c]=1
# extras
for r,c,v in [(15,0,2),(0,14,9),(1,15,9)]: g[r][c]=v
# transpose completion without replacing existing values
for r in range(n):
 for c in range(n):
  if g[r][c]:
   if not g[c][r]: g[c][r]=g[r][c]
print(json.dumps(g))
